package org.openrecorder.app.core

import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.exp
import kotlin.math.ln
import kotlin.math.log10
import kotlin.math.max
import kotlin.math.min
import kotlin.math.sin
import kotlin.math.sqrt

/** Recording situations the automatic mode can tell apart by sound. */
enum class Scene { Conference, Meeting, Memo, Ambient }

/**
 * Listens to the start of a recording and decides its [Scene].
 *
 * Ported operation for operation from the Python reference used for tuning (`scene2/feat2.py`).
 * 48 kHz input is decimated to 16 kHz by two cascaded 3-tap box filters; analysis frames are 512
 * samples (32 ms) with a 160 sample hop and a periodic Hann window. Window features are computed
 * over the last 3, 10 and 30 s (55 each), and a small MLP picks the scene. The decision is
 * committed once its probability reaches [THRESHOLD] after 3 s, and at [DEADLINE] at the latest.
 *
 * All buffers are allocated in the constructor; [feed] allocates nothing.
 */
class SceneDetector(private val rate: Int) {
    init {
        require(rate == RATE16 || rate == RATE48) { "rate must be 16000 or 48000" }
    }

    private val decim = rate / RATE16

    private companion object {
    private const val W1_A = ""
    private const val W1_B = ""
    private const val B1_B64 = ""
    private const val W2_B64 = ""
    private const val B2_B64 = "2mJRPUb4Cj7cja+9cNOFPeO4bzvP9ty8XcRnPNe0hLv3m2I9CpyaPAoBvz3xP/m8G0XKu9orQT3AZGC98smgPSA7Zj3Oi749X38iPlRslj2uBia9Vn5wvV+MobzXmTe9/u8mvTQL/Toww8w9eWrgPT0GXjxpbI68/RMXvWInDz0="
    private const val W3_B64 = ""
    private const val B3_B64 = "AoglPcneBj0DKOO8kgysvQ=="
    private const val MU_B64 = ""
    private const val SD_B64 = ""
        const val RATE16 = 16000
        const val RATE48 = 48000
        const val FRAME = 512
        const val HOP = 160
        const val MAXW = 3000
        const val SCALE0 = 300
        const val SCALE1 = 1000
        const val SCALE2 = 3000
        const val NF = 55
        const val NF3 = 165
        const val H1 = 64
        const val H2 = 32
        const val EPS = 1e-20
        const val CHECK_FIRST = 3.0
        const val CHECK_STEP = 0.5
        const val DEADLINE = 29.9
        const val THRESHOLD = 0.97f
        const val STABLE = 1
        const val EMA = 0.5
        const val TEMP = 1.92f
        const val LO_BIN = 3
        const val HI_BIN = 191
        const val BAND_BINS = HI_BIN - LO_BIN + 1
    }

    private val order = arrayOf(Scene.Conference, Scene.Meeting, Scene.Memo, Scene.Ambient)

    // ------------------------------------------------------------ input path
    private var xPrev1 = 0.0
    private var xPrev2 = 0.0
    private var f1Prev1 = 0.0
    private var f1Prev2 = 0.0
    private var inputIndex = 0L
    private var totalSamples = 0L

    private val frameRing = DoubleArray(FRAME)
    private var frameWrite = 0
    private var frameFill = 0
    private var sinceHop = 0
    private var framesDone = 0

    // ------------------------------------------------------------ frame spectra
    private val hann = DoubleArray(FRAME) { 0.5 - 0.5 * cos(2.0 * PI * it / FRAME) }
    private val cosTab = DoubleArray(FRAME / 2) { cos(2.0 * PI * it / FRAME) }
    private val sinTab = DoubleArray(FRAME / 2) { -sin(2.0 * PI * it / FRAME) }
    private val bitRev = IntArray(FRAME).also { rev ->
        var j = 0
        for (i in 0 until FRAME) {
            rev[i] = j
            var bit = FRAME shr 1
            while (bit != 0 && (j and bit) != 0) {
                j = j xor bit
                bit = bit shr 1
            }
            j = j or bit
        }
    }
    private val re = DoubleArray(FRAME)
    private val im = DoubleArray(FRAME)
    private val power = DoubleArray(FRAME / 2 + 1)
    private val prevBand = DoubleArray(4)
    private var firstFrame = true

    // ------------------------------------------------------------ feature rings
    private val dbRing = DoubleArray(MAXW)
    private val hfRing = DoubleArray(MAXW)
    private val fluxRing = DoubleArray(MAXW)
    private val zcrRing = DoubleArray(MAXW)
    private val peakRing = DoubleArray(MAXW)
    private val flatRing = DoubleArray(MAXW)
    private val centRing = DoubleArray(MAXW)
    private val harmRing = DoubleArray(MAXW)
    private val b0Ring = DoubleArray(MAXW)
    private val b1Ring = DoubleArray(MAXW)
    private val b3Ring = DoubleArray(MAXW)
    private val b1b0Ring = DoubleArray(MAXW)
    private var ringPos = 0

    // ------------------------------------------------------------ window scratch
    private val wDb = DoubleArray(MAXW)
    private val wHf = DoubleArray(MAXW)
    private val wFlux = DoubleArray(MAXW)
    private val wZcr = DoubleArray(MAXW)
    private val wPeak = DoubleArray(MAXW)
    private val wFlat = DoubleArray(MAXW)
    private val wCent = DoubleArray(MAXW)
    private val wHarm = DoubleArray(MAXW)
    private val wB0 = DoubleArray(MAXW)
    private val wB1 = DoubleArray(MAXW)
    private val wB3 = DoubleArray(MAXW)
    private val wB1B0 = DoubleArray(MAXW)
    private val sortA = DoubleArray(MAXW)
    private val sortB = DoubleArray(MAXW)
    private val d5 = DoubleArray(MAXW)
    private val slopes = DoubleArray(MAXW)
    private val runs = IntArray(MAXW)
    private val per = DoubleArray(MAXW / 100 + 1)
    private val actMask = BooleanArray(MAXW)
    private val feat = DoubleArray(NF3)

    // ------------------------------------------------------------ classifier
    private val mu = decodeFloats(MU_B64, "")
    private val sd = decodeFloats(SD_B64, "")
    private val w1 = decodeFloats(W1_A, W1_B)
    private val b1 = decodeFloats(B1_B64, "")
    private val w2 = decodeFloats(W2_B64, "")
    private val b2 = decodeFloats(B2_B64, "")
    private val w3 = decodeFloats(W3_B64, "")
    private val b3 = decodeFloats(B3_B64, "")
    private val xin = DoubleArray(NF3)
    private val h1 = DoubleArray(H1)
    private val h2 = DoubleArray(H2)
    private val out = DoubleArray(4)

    // ------------------------------------------------------------ result
    private var nextCheck = CHECK_FIRST
    private var decidedScene: Scene? = null
    private var streak = 0
    private var streakClass = -1
    private val pe = DoubleArray(4)
    private var hasPe = false

    /** Input sample index at which the decision was committed, or -1. */
    var decidedSample: Long = -1
        private set

    /** Mono samples in [-1, 1] at the capture rate. Returns the scene once decided (and on every later call), else null. */
    fun feed(samples: FloatArray, count: Int = samples.size): Scene? {
        decidedScene?.let { return it }
        val n = min(max(count, 0), samples.size)
        for (i in 0 until n) {
            val xd = samples[i].toDouble()
            if (decim == 1) {
                pushDecimated(xd)
            } else {
                val f1 = (xd + xPrev1 + xPrev2) / 3.0
                val f2 = (f1 + f1Prev1 + f1Prev2) / 3.0
                xPrev2 = xPrev1
                xPrev1 = xd
                f1Prev2 = f1Prev1
                f1Prev1 = f1
                if (inputIndex % 3L == 0L) pushDecimated(f2)
            }
            inputIndex++
        }
        totalSamples += n
        val t = totalSamples.toDouble() / rate
        if (t >= nextCheck && framesDone >= SCALE0) {
            computeWindow(SCALE0, 0)
            computeWindow(SCALE1, NF)
            computeWindow(SCALE2, 2 * NF)
            classify()
            if (EMA > 0.0 && hasPe) {
                for (k in 0 until 4) pe[k] = (1.0 - EMA) * pe[k] + EMA * out[k]
            } else {
                for (k in 0 until 4) pe[k] = out[k]
                hasPe = true
            }
            var best = 0
            for (k in 1 until 4) if (pe[k] > pe[best]) best = k
            streak = if (best == streakClass) streak + 1 else 1
            streakClass = best
            if (t >= DEADLINE) {
                commit(best)
            } else if (pe[best] >= THRESHOLD && streak >= STABLE) {
                commit(best)
            }
            nextCheck = if (decidedScene != null || t >= DEADLINE) Double.MAX_VALUE
            else min(nextCheck + CHECK_STEP, DEADLINE)
        }
        return decidedScene
    }

    private fun commit(c: Int) {
        decidedScene = order[c]
        decidedSample = totalSamples
    }

    private fun pushDecimated(v: Double) {
        frameRing[frameWrite] = v
        frameWrite++
        if (frameWrite == FRAME) frameWrite = 0
        if (frameFill < FRAME) frameFill++
        sinceHop++
        if (frameFill == FRAME && sinceHop >= HOP) {
            processFrame()
            sinceHop = 0
        }
    }

    // ------------------------------------------------------------ frame features
    private fun fft() {
        for (i in 0 until FRAME) {
            val j = bitRev[i]
            if (j > i) {
                val tr = re[i]; re[i] = re[j]; re[j] = tr
                val ti = im[i]; im[i] = im[j]; im[j] = ti
            }
        }
        var len = 2
        while (len <= FRAME) {
            val half = len shr 1
            val step = FRAME / len
            var base = 0
            while (base < FRAME) {
                var k = 0
                var j = base
                while (j < base + half) {
                    val wr = cosTab[k]
                    val wi = sinTab[k]
                    val ur = re[j]
                    val ui = im[j]
                    val vr = re[j + half] * wr - im[j + half] * wi
                    val vi = re[j + half] * wi + im[j + half] * wr
                    re[j] = ur + vr
                    im[j] = ui + vi
                    re[j + half] = ur - vr
                    im[j + half] = ui - vi
                    j++
                    k += step
                }
                base += len
            }
            len = len shl 1
        }
    }

    private fun processFrame() {
        var idx = frameWrite
        for (i in 0 until FRAME) {
            re[i] = frameRing[idx] * hann[i]
            im[i] = 0.0
            idx++
            if (idx == FRAME) idx = 0
        }
        fft()
        var b0 = 0.0
        var b1 = 0.0
        var b2 = 0.0
        var b3 = 0.0
        var sumLog = 0.0
        var sumCent = 0.0
        for (k in 0..FRAME / 2) power[k] = re[k] * re[k] + im[k] * im[k]
        for (k in LO_BIN..HI_BIN) {
            val p = power[k]
            sumLog += ln(p + EPS)
            sumCent += k * p
            when {
                k <= 15 -> b0 += p
                k <= 47 -> b1 += p
                k <= 95 -> b2 += p
                else -> b3 += p
            }
        }
        val total = b0 + b1 + b2 + b3
        val db = 10.0 * log10(total + EPS)
        val d0 = 10.0 * log10(b0 + EPS)
        val d1 = 10.0 * log10(b1 + EPS)
        val d2 = 10.0 * log10(b2 + EPS)
        val d3 = 10.0 * log10(b3 + EPS)
        val d3rel = 10.0 * log10(b3 / (total + EPS) + EPS)
        val hf = 10.0 * log10((b2 + b3 + EPS) / (b0 + b1 + EPS))
        val b1b0 = 10.0 * log10((b1 + EPS) / (b0 + EPS))
        val flat = exp(sumLog / BAND_BINS.toDouble()) / (total / BAND_BINS.toDouble() + EPS)
        val cent = sumCent / (total + EPS)
        var flux = 0.0
        if (!firstFrame) {
            flux = (max(0.0, d0 - prevBand[0]) + max(0.0, d1 - prevBand[1]) +
                max(0.0, d2 - prevBand[2]) + max(0.0, d3 - prevBand[3])) / 4.0
        } else {
            firstFrame = false
        }
        prevBand[0] = d0
        prevBand[1] = d1
        prevBand[2] = d2
        prevBand[3] = d3
        val zc = zcr()
        var pk = 0.0
        for (k in LO_BIN..HI_BIN) if (power[k] > pk) pk = power[k]
        val peak = pk / (total / BAND_BINS + EPS)
        // normalized autocorrelation peak over lags 40..200 (80..400 Hz)
        for (k in 0..FRAME / 2) {
            re[k] = power[k]
            im[k] = 0.0
        }
        for (k in 1 until FRAME / 2) {
            re[FRAME - k] = power[k]
            im[FRAME - k] = 0.0
        }
        fft()
        val r0 = re[0]
        var harm = 0.0
        if (r0 > 0.0) {
            var mx = -1e30
            for (lag in 40..200) if (re[lag] > mx) mx = re[lag]
            if (mx / r0 > 0.5) harm = 1.0
        }
        dbRing[ringPos] = db
        hfRing[ringPos] = hf
        fluxRing[ringPos] = flux
        zcrRing[ringPos] = zc
        peakRing[ringPos] = peak
        flatRing[ringPos] = flat
        centRing[ringPos] = cent
        harmRing[ringPos] = harm
        b0Ring[ringPos] = d0
        b1Ring[ringPos] = d1
        b3Ring[ringPos] = d3rel
        b1b0Ring[ringPos] = b1b0
        ringPos++
        if (ringPos == MAXW) ringPos = 0
        framesDone++
    }

    private fun zcr(): Double {
        var idx = frameWrite
        var prev = frameRing[idx] >= 0.0
        var count = 0
        var k = 1
        idx++
        if (idx == FRAME) idx = 0
        while (k < FRAME) {
            val v = frameRing[idx] >= 0.0
            if (v != prev) count++
            prev = v
            idx++
            if (idx == FRAME) idx = 0
            k++
        }
        return count.toDouble() / (FRAME - 1)
    }

    // ------------------------------------------------------------ window features
    private fun copyRing(src: DoubleArray, dst: DoubleArray, n: Int) {
        var idx = ringPos - n
        if (idx < 0) idx += MAXW
        for (i in 0 until n) {
            dst[i] = src[idx].toDouble()
            idx++
            if (idx == MAXW) idx = 0
        }
    }

    private fun pct(a: DoubleArray, n: Int, q: Double): Double = a[min(n - 1, (q * (n - 1)).toInt())]

    private fun medianAvg(a: DoubleArray, n: Int): Double {
        if (n == 0) return 0.0
        java.util.Arrays.sort(a, 0, n)
        return if (n % 2 == 1) a[n / 2] else (a[n / 2 - 1] + a[n / 2]) * 0.5
    }

    private fun corr(sxy: Double, sx: Double, sy: Double, sxx: Double, syy: Double,
                     n: Int): Double {
        if (n < 2) return 0.0
        val mx = sx / n
        val my = sy / n
        val vx = sxx / n - mx * mx
        val vy = syy / n - my * my
        if (vx <= 1e-12 || vy <= 1e-12) return 0.0
        return (sxy / n - mx * my) / sqrt(vx * vy)
    }

    private fun computeWindow(scale: Int, base: Int) {
        val n = min(framesDone, scale)
        copyRing(dbRing, wDb, n)
        copyRing(hfRing, wHf, n)
        copyRing(fluxRing, wFlux, n)
        copyRing(zcrRing, wZcr, n)
        copyRing(peakRing, wPeak, n)
        copyRing(flatRing, wFlat, n)
        copyRing(centRing, wCent, n)
        copyRing(harmRing, wHarm, n)
        copyRing(b0Ring, wB0, n)
        copyRing(b1Ring, wB1, n)
        copyRing(b3Ring, wB3, n)
        copyRing(b1b0Ring, wB1B0, n)

        System.arraycopy(wDb, 0, sortA, 0, n)
        java.util.Arrays.sort(sortA, 0, n)
        val p05 = pct(sortA, n, 0.05)
        val p10 = pct(sortA, n, 0.10)
        val p25 = pct(sortA, n, 0.25)
        val p50 = pct(sortA, n, 0.50)
        val p75 = pct(sortA, n, 0.75)
        val p90 = pct(sortA, n, 0.90)
        val p95 = pct(sortA, n, 0.95)

        var actCount = 0
        for (i in 0 until n) if (wDb[i] > p10 + 10.0) actCount++
        var mean = 0.0
        for (i in 0 until n) mean += wDb[i]
        mean /= n
        var variance = 0.0
        for (i in 0 until n) {
            val d = wDb[i] - mean
            variance += d * d
        }
        variance = variance / n + 1e-12

        var low = 0.0
        var beat = 0.0
        var syl = 0.0
        for (k in 0 until 17) {
            val step = 2.0 * PI * (k + 2) / n
            val wr = cos(step)
            val wi = sin(step)
            var xr = 1.0
            var xi = 0.0
            var cr = 0.0
            var ci = 0.0
            for (i in 0 until n) {
                val d = wDb[i] - mean
                cr += d * xr
                ci += d * xi
                val nx = xr * wr - xi * wi
                xi = xr * wi + xi * wr
                xr = nx
            }
            val pwr = cr * cr + ci * ci
            when {
                k < 4 -> low += pwr
                k < 7 -> beat += pwr
                else -> syl += pwr
            }
        }
        val modTot = low + beat + syl + 1e-12

        var sdSum = 0.0
        for (i in 0 until n) {
            val d = wDb[i] - mean
            sdSum += d * d
        }
        val sd = sqrt(sdSum / n)

        var dec15 = 0.0
        if (n > 25) {
            val m = n - 5
            for (i in 0 until m) d5[i] = wDb[i + 5] - wDb[i]
            java.util.Arrays.sort(d5, 0, m)
            dec15 = pct(d5, m, 0.15)
        }

        var decay = 0.0
        var slopeCount = 0
        for (i in 2 until n - 20) {
            if (wDb[i] > p75 && wDb[i] >= wDb[i - 1] && wDb[i] >= wDb[i - 2]) {
                var vMin = 1e30
                var jBest = 0
                for (j in 0..20) {
                    val v = wDb[i + j]
                    if (v < vMin) {
                        vMin = v
                        jBest = j
                    }
                }
                val drop = wDb[i] - vMin
                if (drop > 6.0 && vMin > p10 + 3.0 && jBest > 0) {
                    slopes[slopeCount++] = -drop / (0.01 * jBest)
                }
            }
        }
        if (slopeCount > 0) decay = medianAvg(slopes, slopeCount)

        var dSum = 0.0
        for (i in 1 until n) dSum += abs(wDb[i] - wDb[i - 1])
        val rough = (dSum / (n - 1)) / (sd + 1e-9)
        val ac1: Double
        if (sd > 1e-6) {
            var sxy = 0.0
            var sx = 0.0
            var sy = 0.0
            var sxx = 0.0
            var syy = 0.0
            for (i in 0 until n - 1) {
                val x = wDb[i]
                val y = wDb[i + 1]
                sxy += x * y
                sx += x
                sy += y
                sxx += x * x
                syy += y * y
            }
            ac1 = corr(sxy, sx, sy, sxx, syy, n - 1)
        } else {
            ac1 = 1.0
        }
        val ac10 = if (n > 40) lagCorr(10, n) else 0.0
        val ac30 = if (n > 70) lagCorr(30, n) else 0.0

        var cSxy = 0.0
        var cSx = 0.0
        var cSy = 0.0
        var cSxx = 0.0
        var cSyy = 0.0
        var hdSum = 0.0
        var hdSq = 0.0
        for (i in 0 until n) {
            val x = wB0[i]
            val y = wB1[i]
            cSxy += x * y
            cSx += x
            cSy += y
            cSxx += x * x
            cSyy += y * y
            val hd = wB3[i] - wB0[i]
            hdSum += hd
            hdSq += hd * hd
        }
        val c01 = corr(cSxy, cSx, cSy, cSxx, cSyy, n)
        val hdMu = hdSum / n
        val hfdiff = sqrt(max(0.0, hdSq / n - hdMu * hdMu))

        var actN = 0
        for (i in 0 until n) {
            val a = wDb[i] > p10 + 8.0
            actMask[i] = a
            if (a) actN++
        }
        if (actN < 40) {
            for (i in 0 until n) actMask[i] = true
            actN = n
        }
        var sumDb = 0.0
        var sumDb2 = 0.0
        var sumDb3 = 0.0
        var sB0x = 0.0
        var sB1y = 0.0
        var sB0xy = 0.0
        var sB0xx = 0.0
        var sB1yy = 0.0
        var sumHd = 0.0
        var sumHd2 = 0.0
        var sumHf = 0.0
        var sumHerm = 0.0
        var sumCent = 0.0
        var pairN = 0
        var pairSum = 0.0
        for (i in 0 until n) {
            if (!actMask[i]) continue
            val v = wDb[i]
            sumDb += v
            sumDb2 += v * v
            sumDb3 += v * v * v
            val x = wB0[i]
            val y = wB1[i]
            sB0x += x
            sB1y += y
            sB0xy += x * y
            sB0xx += x * x
            sB1yy += y * y
            val hd = wB3[i] - wB0[i]
            sumHd += hd
            sumHd2 += hd * hd
            sumHf += wHf[i]
            sumHerm += wHarm[i]
            sumCent += wCent[i]
            if (i > 0 && actMask[i - 1]) {
                pairSum += abs(wDb[i] - wDb[i - 1])
                pairN++
            }
        }
        val nAct = actN.toDouble()
        val muA = sumDb / nAct
        val varA = max(0.0, sumDb2 / nAct - muA * muA)
        val sdA = sqrt(varA)
        val skew = (sumDb3 / nAct - 3.0 * muA * (sumDb2 / nAct) + 2.0 * muA * muA * muA) /
            (sdA * sdA * sdA + 1e-9)

        var k = 0
        for (i in 0 until n) if (actMask[i]) sortB[k++] = wDb[i]
        java.util.Arrays.sort(sortB, 0, actN)
        val rangeA = pct(sortB, actN, 0.95) - pct(sortB, actN, 0.05)

        k = 0
        for (i in 0 until n) if (actMask[i]) sortB[k++] = wFlat[i]
        val flatA = medianAvg(sortB, actN)

        k = 0
        for (i in 0 until n) if (actMask[i]) sortB[k++] = wCent[i]
        var centMu = 0.0
        for (i in 0 until actN) centMu += sortB[i]
        centMu /= nAct
        var centVar = 0.0
        for (i in 0 until actN) centVar += (sortB[i] - centMu) * (sortB[i] - centMu)
        val centsda = sqrt(max(0.0, centVar / nAct))

        val roughA = if (pairN > 20) (pairSum / pairN) / (sdA + 1e-9) else 0.0
        val c01a = corr(sB0xy, sB0x, sB1y, sB0xx, sB1yy, actN)
        val hdMuA = sumHd / nAct
        val hfdiffa = sqrt(max(0.0, sumHd2 / nAct - hdMuA * hdMuA))
        val hfa = sumHf / nAct
        val harma = sumHerm / nAct

        System.arraycopy(wFlat, 0, sortB, 0, n)
        java.util.Arrays.sort(sortB, 0, n)
        val flat = pct(sortB, n, 0.50)
        System.arraycopy(wB3, 0, sortB, 0, n)
        java.util.Arrays.sort(sortB, 0, n)
        val b3 = pct(sortB, n, 0.50)

        var b1b0Sum = 0.0
        var zcrSum = 0.0
        var zcr2 = 0.0
        var peakSum = 0.0
        var hfSum = 0.0
        var hf2 = 0.0
        var fluxSum = 0.0
        var flux2 = 0.0
        var centSum2 = 0.0
        var cent2 = 0.0
        var harmSum = 0.0
        for (i in 0 until n) {
            b1b0Sum += wB1B0[i]
            zcrSum += wZcr[i]
            zcr2 += wZcr[i] * wZcr[i]
            peakSum += wPeak[i]
            hfSum += wHf[i]
            hf2 += wHf[i] * wHf[i]
            fluxSum += wFlux[i]
            flux2 += wFlux[i] * wFlux[i]
            centSum2 += wCent[i]
            cent2 += wCent[i] * wCent[i]
            harmSum += wHarm[i]
        }
        val nd = n.toDouble()
        val hfMu = hfSum / nd
        val hfsd = sqrt(max(0.0, hf2 / nd - hfMu * hfMu))
        val fluxMu = fluxSum / nd
        val fluxSd = sqrt(max(0.0, flux2 / nd - fluxMu * fluxMu))
        val centMu2 = centSum2 / nd
        val centsd = sqrt(max(0.0, cent2 / nd - centMu2 * centMu2))

        val chunks = n / 100
        var chunkSd = 0.0
        var chunkRng = 0.0
        var chunkDiff = 0.0
        var perN = 0
        for (c in 0 until chunks) {
            var acc = 0.0
            for (i in 0 until 100) acc += wDb[c * 100 + i]
            per[perN++] = acc / 100.0
        }
        if (perN > 1) {
            var pm = 0.0
            for (i in 0 until perN) pm += per[i]
            pm /= perN
            var pv = 0.0
            var pd = 0.0
            for (i in 0 until perN) {
                pv += (per[i] - pm) * (per[i] - pm)
                if (i > 0) pd += abs(per[i] - per[i - 1])
            }
            chunkSd = sqrt(max(0.0, pv / perN))
            chunkDiff = pd / (perN - 1)
            java.util.Arrays.sort(per, 0, perN)
            chunkRng = pct(per, perN, 0.90) - pct(per, perN, 0.10)
        }

        var pauseCount = 0
        var runLen = 0
        var runN = 0
        for (i in 0 until n) {
            if (wDb[i] < p50 - 10.0) {
                pauseCount++
                runLen++
            } else if (runLen > 0) {
                runs[runN++] = runLen
                runLen = 0
            }
        }
        if (runLen > 0) runs[runN++] = runLen
        java.util.Arrays.sort(runs, 0, runN)
        val pauseFrac = pauseCount.toDouble() / n
        val pauseMed = if (runN == 0) 0.0 else if (runN % 2 == 1) runs[runN / 2].toDouble()
        else (runs[runN / 2 - 1] + runs[runN / 2]) * 0.5

        var onset = 0
        for (i in 3 until n) if (wDb[i] - wDb[i - 3] > 6.0) onset++
        val onsetRate = onset.toDouble() / (n - 3) * 100.0 / 3.0

        var act2 = 0
        k = 0
        for (i in 0 until n) {
            if (wDb[i] > p50 + 10.0) {
                act2++
                sortB[k++] = wDb[i]
            }
        }
        var actRng = 0.0
        if (act2 > 20) {
            java.util.Arrays.sort(sortB, 0, act2)
            actRng = pct(sortB, act2, 0.95) - pct(sortB, act2, 0.05)
        }

        feat[base + 0] = p05
        feat[base + 1] = p10
        feat[base + 2] = p25
        feat[base + 3] = p50
        feat[base + 4] = p75
        feat[base + 5] = p90
        feat[base + 6] = p95
        feat[base + 7] = p90 - p10
        feat[base + 8] = p95 - p05
        feat[base + 9] = actCount.toDouble() / n
        feat[base + 10] = p50 - p10
        feat[base + 11] = p95 - p50
        feat[base + 12] = low / (n * variance)
        feat[base + 13] = beat / (n * variance)
        feat[base + 14] = syl / (n * variance)
        feat[base + 15] = syl / modTot
        feat[base + 16] = low / modTot
        feat[base + 17] = dec15
        feat[base + 18] = decay
        feat[base + 19] = fluxMu
        feat[base + 20] = fluxSd
        feat[base + 21] = hfMu
        feat[base + 22] = hfsd
        feat[base + 23] = flat
        feat[base + 24] = centsd
        feat[base + 25] = harmSum / nd
        feat[base + 26] = b3
        feat[base + 27] = b1b0Sum / nd
        feat[base + 28] = c01
        feat[base + 29] = hfdiff
        feat[base + 30] = ac1
        feat[base + 31] = rough
        feat[base + 32] = zcrSum / nd
        feat[base + 33] = sqrt(max(0.0, zcr2 / nd - (zcrSum / nd) * (zcrSum / nd)))
        feat[base + 34] = peakSum / nd
        feat[base + 35] = sdA
        feat[base + 36] = skew
        feat[base + 37] = rangeA
        feat[base + 38] = roughA
        feat[base + 39] = harma
        feat[base + 40] = flatA
        feat[base + 41] = centsda
        feat[base + 42] = hfa
        feat[base + 43] = hfdiffa
        feat[base + 44] = c01a
        feat[base + 45] = chunkSd
        feat[base + 46] = chunkRng
        feat[base + 47] = pauseFrac
        feat[base + 48] = pauseMed
        feat[base + 49] = onsetRate
        feat[base + 50] = act2.toDouble() / n
        feat[base + 51] = actRng
        feat[base + 52] = ac10
        feat[base + 53] = ac30
        feat[base + 54] = chunkDiff
    }

    private fun lagCorr(lag: Int, n: Int): Double {
        var sxy = 0.0
        var sx = 0.0
        var sy = 0.0
        var sxx = 0.0
        var syy = 0.0
        val m = n - lag
        for (i in 0 until m) {
            val x = wDb[i]
            val y = wDb[i + lag]
            sxy += x * y
            sx += x
            sy += y
            sxx += x * x
            syy += y * y
        }
        return corr(sxy, sx, sy, sxx, syy, m)
    }

    // ------------------------------------------------------------ classifier
    private fun classify(): Int {
        for (i in 0 until NF3) xin[i] = (feat[i] - mu[i]) / sd[i]
        for (j in 0 until H1) {
            var s = b1[j].toDouble()
            for (i in 0 until NF3) s += xin[i] * w1[i * H1 + j]
            h1[j] = max(0.0, s)
        }
        for (j in 0 until H2) {
            var s = b2[j].toDouble()
            for (i in 0 until H1) s += h1[i] * w2[i * H2 + j]
            h2[j] = max(0.0, s)
        }
        var best = 0
        for (j in 0 until 4) {
            var s = b3[j].toDouble()
            for (i in 0 until H2) s += h2[i] * w3[i * 4 + j]
            out[j] = s
            if (s > out[best]) best = j
        }
        val m = max(max(out[0], out[1]), max(out[2], out[3]))
        var sum = 0.0
        for (j in 0 until 4) {
            out[j] = exp((out[j] - m) / TEMP)
            sum += out[j]
        }
        for (j in 0 until 4) out[j] /= sum
        return best
    }

    private fun decodeFloats(a: String, b: String): FloatArray {
        val s = if (b.isEmpty()) a else a + b
        val bytes = java.util.Base64.getDecoder().decode(s)
        val buf = java.nio.ByteBuffer.wrap(bytes).order(java.nio.ByteOrder.LITTLE_ENDIAN)
        return FloatArray(bytes.size / 4) { buf.float }
    }
}
